public class ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}

public int compareLists(ListNode headA, ListNode headB) {
    ListNode a = headA;
    ListNode b = headB;
    while (a != null && b != null) {
        if (a.val != b.val) {
            return 0;
        }
        a = a.next;
        b = b.next;
    }
    return (a == null && b == null) ? 1 : 0;
}

