class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def compareLists(self, headA: ListNode, headB: ListNode) -> int:
    a = headA
    b = headB
    while a is not None and b is not None:
        if a.val != b.val:
            return 0
        a = a.next
        b = b.next
    return 1 if a is None and b is None else 0

